use AutoAgora\Dealer\Review;
use AutoAgora\Dealer\Listings;
use AutoAgora\Dealer\Reviewer;
$assets = get_stylesheet_directory_uri() . '/includes/dealer-integration/assets/';
$user = wp_get_current_user();
$pageTitle = ['connections' => 'Dealer connections', 'stock' => 'Dealer stock', 'activity' => 'Integration activity', 'access' => 'Reviewer access'][$tab];
$dealerNames = [];
foreach ($state['dealers'] as $dealer) { $dealerNames[(int) $dealer->ID] = $dealer->display_name; }
$connectionRows = [];
foreach ($state['dealers'] as $dealer) {
    $matches = array_values(array_filter($state['connections'], static fn ($c) => (int) $c['dealer_id'] === (int) $dealer->ID));
    foreach ($matches ?: [null] as $connection) {
        $application = $connection ? Workspace::clientName($connection['client_id'], $state['clients']) : '';
        if ($search !== '' && stripos($dealer->display_name . ' ' . $application, $search) === false) { continue; }
        $connectionRows[] = [$dealer, $connection, $application];
    }
}
